import{_ as t,o as r,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Architecture","description":"Packages, événements, services et principes de l’architecture modulaire ATLAS.","frontmatter":{"title":"Architecture","description":"Packages, événements, services et principes de l’architecture modulaire ATLAS."},"headers":[],"relativePath":"fr/projects/atlas/overview.md","filePath":"fr/projects/atlas/overview.md","lastUpdated":1792851775000}'),d={name:"fr/projects/atlas/overview.md"};function i(n,e,o,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>ATLAS est un monorepo TypeScript modulaire. Les contrats communs séparent les services, la présentation et l’intégration avec l’environnement hôte.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Rôle</th></tr></thead><tbody><tr><td><code>@atlas/core</code></td><td>Contrats et types centraux.</td></tr><tr><td><code>@atlas/foundation</code></td><td>Infrastructure et composants communs.</td></tr><tr><td><code>@atlas/runtime</code></td><td>Services d’exécution et conteneur de services.</td></tr><tr><td><code>@atlas/renderer</code></td><td>Présentation et abstractions du moteur de rendu.</td></tr><tr><td><code>@atlas/homeassistant</code></td><td>Intégration et workflows Home Assistant.</td></tr><tr><td><code>@atlas/theme</code></td><td>Thèmes et conception visuelle partagés.</td></tr><tr><td><code>@atlas/devtools</code></td><td>Diagnostics et outils de développement.</td></tr><tr><td><code>@atlas/kernel</code></td><td>Contrats des modules, conteneur de services et infrastructure.</td></tr><tr><td><code>@atlas/workspace</code></td><td>Contrats de préparation des espaces de travail.</td></tr><tr><td><code>@atlas/file-studio</code></td><td>Contrats et adaptateur Runtime internes ; le plugin web installable reste externe.</td></tr><tr><td><code>@atlas/notifyarchive</code></td><td>Contrats internes des archives de notifications.</td></tr></tbody></table><h2 id="principes-d-architecture" tabindex="-1">Principes d’architecture <a class="header-anchor" href="#principes-d-architecture" aria-label="Permalink to &quot;Principes d’architecture&quot;">​</a></h2><ul><li>Séparer les contrats de leurs implémentations.</li><li>Utiliser de petits modules remplaçables.</li><li>Concevoir des composants testables.</li><li>Définir explicitement les interfaces et les dépendances.</li><li>Fournir des implémentations de référence.</li><li>Préparer l’extension par des plugins à long terme.</li></ul><h2 id="evenements" tabindex="-1">Événements <a class="header-anchor" href="#evenements" aria-label="Permalink to &quot;Événements&quot;">​</a></h2><p>Les contrats comprennent <code>Event</code>, <code>EventBus</code>, <code>Handler</code>, <code>Subscription</code>, <code>Filter</code>, <code>Publisher</code> et <code>Subscriber</code>. <code>DefaultEventBus</code> fournit l’implémentation de référence.</p><h2 id="services-et-injection-de-dependances" tabindex="-1">Services et injection de dépendances <a class="header-anchor" href="#services-et-injection-de-dependances" aria-label="Permalink to &quot;Services et injection de dépendances&quot;">​</a></h2><p>Les descripteurs et l’enregistrement des services, l’injection de dépendances et les conteneurs permettent de résoudre les services de manière contrôlée.</p><h2 id="utilisations-prevues" tabindex="-1">Utilisations prévues <a class="header-anchor" href="#utilisations-prevues" aria-label="Permalink to &quot;Utilisations prévues&quot;">​</a></h2><p>ATLAS vise les outils Home Assistant, les composants de tableaux de bord, les applications de diagnostic et les applications web ou de bureau basées sur des plugins. La carte Lovelace UV reste un projet ultérieur.</p><p>Les contrats sont encore en développement : cette architecture ne constitue pas une promesse d’API de plugin stable. Voir l’<a href="/fr/projects/atlas/development-status">état du développement</a>.</p>',13)])])}const h=t(d,[["render",i]]);export{m as __pageData,h as default};
